sp_widget.client_script:
api.controller = function($interval, $scope) {
   var c = this;

   //Summary details for errro and Valid records
    var totalCount = c.data.totalRecordCount;
    var totalErrorRecords = c.data.summaryErrorRecords;
    var totalValidRecords = c.data.summaryValidRecords;

    c.isLoading = true;
    c.progress = 0;
    c.errorList = []; // This will hold ALL errors received from the server

    // Check what the server sends (simulate for now)
    var serverResponse = c.data || {};

    // Message flag
    c.noErrorsMessage = "";

    // --- Pagination Variables and Functions ---
    c.pageSize = 10; // Number of items per page. Adjust as needed.
    c.currentPage = 1;
    c.totalErrors = 0;
    c.totalPages = 0;
    c.currentPageErrors = []; // This will hold errors for the current page
    c.pagesToShow = []; // Array to hold the page numbers for display

    c.updatePagination = function() {
        c.totalErrors = c.errorList.length;
        c.totalPages = Math.ceil(c.totalErrors / c.pageSize);

        // Ensure current page is within valid bounds
        if (c.currentPage < 1) {
            c.currentPage = 1;
        }
        if (c.currentPage > c.totalPages && c.totalPages > 0) {
            c.currentPage = c.totalPages;
        }
        if (c.totalPages === 0) { // Handle case with no errors
            c.currentPage = 1;
        }

        var startIndex = (c.currentPage - 1) * c.pageSize;
        var endIndex = startIndex + c.pageSize;
        c.currentPageErrors = c.errorList.slice(startIndex, endIndex);

        c.pagesToShow = c.getPagesToShow();
    };

    c.setPage = function(page) {
        if (typeof page === 'number' && page >= 1 && page <= c.totalPages) {
            c.currentPage = page;
            c.updatePagination();
        } else if (page === '...') {
            return;
        }
    };

    c.range = function(min, max, step) {
        step = step || 1;
        var input = [];
        for (var i = min; i <= max; i += step) {
            input.push(i);
        }
        return input;
    };

    c.getPagesToShow = function() {
        var pages = [];
        var startPage, endPage;
        var maxPages = 7; // Maximum number of page buttons to show (e.g., 5-7)

        if (c.totalPages <= maxPages) {
            startPage = 1;
            endPage = c.totalPages;
        } else {
            var middle = Math.ceil(maxPages / 2);
            if (c.currentPage <= middle) {
                startPage = 1;
                endPage = maxPages;
            } else if (c.currentPage + middle - 1 >= c.totalPages) {
                startPage = c.totalPages - maxPages + 1;
                endPage = c.totalPages;
            } else {
                startPage = c.currentPage - middle + 1;
                endPage = c.currentPage + middle - 1;
            }
        }

        for (var i = startPage; i <= endPage; i++) {
            pages.push(i);
        }

        if (startPage > 1) {
            if (startPage > 2) {
                pages.unshift('...');
            }
            pages.unshift(1);
        }

        if (endPage < c.totalPages) {
            if (endPage < c.totalPages - 1) {
                pages.push('...');
            }
            pages.push(c.totalPages);
        }

        return pages;
    };

    // --- NEW FUNCTION FOR EXPORT TO CSV ---
    c.downloadErrorsAsCsv = function() {
        if (c.errorList.length === 0) {
            alert("No data to export.");
            return;
        }

        // Define CSV headers based on your table columns
        var headers = ["Trade Reference", "Market", "Invalid Reason"];
        var csv = headers.join(",") + "\n"; // Start with headers

        // Iterate through the entire errorList and add to CSV
        c.errorList.forEach(function(row) {
            var tradeRef = row.tradeRef ? '"' + row.tradeRef.replace(/"/g, '""') + '"' : "";
            var tradeMarket = row.tradeMarket ? '"' + row.tradeMarket.replace(/"/g, '""') + '"' : "";
            var inValidReason = row.inValidReason ? '"' + row.inValidReason.replace(/"/g, '""') + '"' : "";

            csv += [tradeRef, tradeMarket, inValidReason].join(",") + "\n";
        });

        // Create a Blob and download the file
        var blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
        var a = document.createElement('a');
        var url = URL.createObjectURL(blob);
        a.href = url;
        a.download = "Validation_Errors_" + new Date().toISOString().slice(0, 10) + ".csv"; // Filename with date
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url); // Clean up
    };
    // --- END NEW FUNCTION ---

    // Simulate data load (replace this with actual async call)
    setTimeout(function() {
        c.isLoading = false;
        c.errorList = Array.isArray(serverResponse.errorList) ? serverResponse.errorList : [];
        c.updatePagination(); // Initial call to setup pagination
        if (c.errorList.length === 0) {
            c.noErrorsMessage = "Validation Successful. No Errors found for the uploaded transaction references";
        } else {
            c.noErrorsMessage = "Validation completed with errors. Please check the details.";
        }
        if (progressInterval) {
            $interval.cancel(progressInterval);
        }
        if (!$scope.$$phase) $scope.$apply();
        $scope.close({
            status: 'dataLoaded',
            errorList: c.errorList,
            noErrors: c.errorList.length === 0,
            message: c.noErrorsMessage
        });
    }, 3000);

    c.progress = 0;
    var progressInterval = $interval(function() {
        if (c.progress < 100) {
            c.progress += 5;
        } else {
            c.progress = 0;
        }
    }, 200);

    c.closeModal = function(action) {
        $scope.close({
            status: action,
            errorList: c.errorList,
            noErrors: c.errorList.length === 0,
            message: c.noErrorsMessage
        });
    };
};

sp_widget.css:
/* HSBC Theme for Validation Errors Widget */

/* Overall Panel Styling */
.panel.panel-default {
    border-color: #DB0011; /* HSBC Red for the border */
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1); /* Subtle shadow for depth */
}

/* Panel Heading - Container for Logo, Title, and Spacer */
.panel-heading {
    background-color: #ffffff; /* HEADER BACKGROUND IS WHITE */
    border-color: #DB0011; /* Ensure border matches your theme */
    padding: 10px 20px; /* Adjust padding for white spacing around the logo and title area */

    /* Flexbox properties for layout */
    display: flex;
    align-items: center; /* Vertically center all items (logo, title, spacer) */
    justify-content: space-between; /* Distribute items with space between them */
}

/* HSBC Logo Styling (left aligned) */
.hsbc-logo-left {
    height: 35px; /* Adjust height for clear visibility of the SVG logo */
    width: auto; /* Maintain aspect ratio */
    flex-shrink: 0; /* Prevent logo from shrinking */
    margin-right: 15px; /* Add some space between logo and title */
    flex: 0 0 auto; /* Don't grow, don't shrink, base size on content */
}

/* Centered Title Styling */
.panel-title-centered {
    flex-grow: 1; /* ALLOW IT TO GROW to take available space */
    text-align: center; /* Center text within its own block */
    margin: 0; /* Reset margin to ensure text-align takes full effect within its flex container */

    font-weight: bold; /* No bold */
    font-size: 1.3em;
    text-transform: none; /* Display as "Validation Errors" (Title Case) */
    color: #333333; /* VALIDATION ERRORS TEXT IS BLACK */
    flex-shrink: 0; /* Prevent title from shrinking */
}

/* Spacer div to push the title to the center and logo to the left */
.header-spacer {
    flex-grow: 1; /* This makes the spacer take up all available space on the right */
}

/* Panel Body */
.panel-body {
    background-color: #ffffff; /* Clean white background */
    padding: 20px; /* Consistent padding */
}

/* Progress Bar Styling */
.progress {
    height: 25px; /* Slightly taller progress bar */
    background-color: #e0e0e0; /* Lighter grey for track */
    border-radius: 5px;
    box-shadow: none; /* Remove default bootstrap shadow if any */
}

.progress-bar {
    background-color: #DB0011; /* HSBC Red for the bar itself */
    font-weight: bold;
    line-height: 25px; /* Vertically center text */
    color: #ffffff; /* White text on bar */
}

/* Table Styling for Errors */
.table.table-bordered.table-striped {
    width: 100%;
    margin-bottom: 0;
    border-collapse: collapse; /* Ensure borders collapse for a clean look */
    border: 1px solid #e0e0e0; /* Main outer border for the table */
}

.table.table-bordered.table-striped thead {
    background-color: #DB0011; /* TABLE HEADER BACKGROUND IS HSBC RED */
    color: #ffffff; /* TABLE HEADER TEXT IS WHITE */
}

.table.table-bordered.table-striped th {
    border: 1px solid #e0e0e0; /* Border for header cells */
    border-bottom: 2px solid #DB0011; /* Stronger red line under header - kept for consistency */
    font-weight: bold;
    padding: 12px 15px;
    text-align: center; /* Centered header text */

    position: sticky;
    top: 0;
    z-index: 10;
    /* background-color: #DB0011; - This is redundant with .table.table-bordered.table-striped thead but harmless */
}

.table.table-bordered.table-striped tbody tr:nth-of-type(odd) {
    background-color: #fdfdfd; /* Very subtle off-white for odd rows */
}

.table.table-bordered.table-striped tbody tr:nth-of-type(even) {
    background-color: #ffffff; /* White for even rows */
}

.table.table-bordered.table-striped td {
    border: 1px solid #d0d0d0; /* REVISED: Slightly darker border for body cells */
    padding: 10px 15px;
}

/* Message When No Errors (Success/Empty File) */
.alert.alert-success {
    background-color: #e6ffe6; /* Very light green, almost white, for success */
    border-color: #4CAF50; /* Standard success green border */
    color: #333333; /* Dark grey text for readability */
    font-weight: bold;
    text-align: center;
    padding: 15px;
    border-radius: 5px;
    margin-bottom: 0;
}

/* --- Pagination Styles --- */
.hsbc-pagination {
    margin-top: 20px;
    display: flex;
    justify-content: center; /* Center the pagination links */
    padding-left: 0;
    list-style: none;
    border-radius: 4px;
}

.hsbc-pagination > li {
    display: inline; /* Float li's to next to each other */
}

.hsbc-pagination > li > a,
.hsbc-pagination > li > span {
    position: relative;
    float: left;
    padding: 8px 12px;
    margin-left: -1px;
    line-height: 1.42857143;
    color: #DB0011; /* HSBC Red for links */
    text-decoration: none;
    background-color: #fff;
    border: 1px solid #ddd;
    border-radius: 4px; /* Slight roundness for all buttons */
    /* Add a slight transition for hover effects */
    transition: all 0.2s ease-in-out;
}

.hsbc-pagination > li:first-child > a,
.hsbc-pagination > li:first-child > span {
    margin-left: 0;
    border-top-left-radius: 4px;
    border-bottom-left-radius: 4px;
}

.hsbc-pagination > li:last-child > a,
.hsbc-pagination > li:last-child > span {
    border-top-right-radius: 4px;
    border-bottom-right-radius: 4px;
}

.hsbc-pagination > li > a:hover,
.hsbc-pagination > li > span:hover,
.hsbc-pagination > li > a:focus,
.hsbc-pagination > li > span:focus {
    color: #b3000f; /* Darker red on hover */
    background-color: #eee;
    border-color: #ddd;
    text-decoration: none; /* Ensure no underline on hover */
}

/* --- MOST AGGRESSIVE ACTIVE PAGE STYLE --- */
.hsbc-pagination > li.active > a,
.hsbc-pagination > li.active > span {
    z-index: 1000 !important;
    color: #ffffff !important;
    background-color: #DB0011 !important;
    border: 2px solid #000000 !important;
    font-weight: bold !important;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.7) !important;
    transform: scale(1.2) !important;
    transition: all 0.2s ease-in-out !important;
    text-decoration: none !important;
    border-radius: 6px !important;
    padding: 10px 15px !important;
    margin-left: 0 !important;
}

/* Ensure active styles persist on hover/focus */
.hsbc-pagination > li.active > a:hover,
.hsbc-pagination > li.active > span:hover,
.hsbc-pagination > li.active > a:focus,
.hsbc-pagination > li.active > span:focus {
    color: #ffffff !important;
    background-color: #DB0011 !important;
    border-color: #000000 !important;
    cursor: default !important;
    box-shadow: 0 0 12px rgba(0, 0, 0, 0.8) !important;
}

.hsbc-pagination > .disabled > span,
.hsbc-pagination > .disabled > span:hover,
.hsbc-pagination > .disabled > span:focus,
.hsbc-pagination > .disabled > a,
.hsbc-pagination > .disabled > a:hover,
.hsbc-pagination > .disabled > a:focus {
    color: #777;
    cursor: not-allowed;
    background-color: #fff;
    border-color: #ddd;
}

/* Specific styling for ellipsis to ensure it's not clickable and looks like text */
.hsbc-pagination > li.disabled > span {
    background-color: transparent !important;
    border-color: transparent !important;
    box-shadow: none !important;
    transform: none !important;
    cursor: default !important;
    color: #333 !important;
    font-weight: normal !important;
    padding: 8px 12px !important;
    margin-left: -1px !important;
}

/* Summary Section Styling */
.summary-section {
    margin-bottom: 20px;
    padding: 15px;
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    background-color: #f9f9f9;
    font-size: 1.1em;
}

.summary-section p {
    margin: 5px 0;
    color: #555;
}

.summary-section strong {
    color: #333;
}

/* Specific styling for the summary table within the summary section */
.summary-section .summary-table {
    width: 100%;
    margin-bottom: 0;
}

.summary-section .summary-table th,
.summary-section .summary-table td {
    vertical-align: middle;
    padding: 8px;
    font-size: 1em;
    border: 1px solid #ddd;
    text-align: center;
}

.summary-section .summary-table thead th {
    background-color: #DB0011; /* Set to HSBC Red to match main table header theme */
    font-weight: bold;
    color: #ffffff; /* Set to white to match main table header theme */
}

/* NEW STYLES FOR SUMMARY VALUES & LABEL */
.text-danger-label {
    color: #DB0011; /* Red for the "Total Error Records" label */
    font-weight: bold; /* Make the label bold */
}

.value-error-records {
    font-weight: bold; /* Bold */
    color: #8B0000; /* Red */
}

.value-valid-records {
    font-weight: bold; /* Bold */
    color: #006400; /* Green */
}

.value-total-records {
    font-weight: bold; /* Bold */
    color: #000000; /* Black */
}

sp_widget.script:
(function() {

    var currentUser = gs.getUser().getName(); //to fetch the right attachment by user
    var getTempAttachment = new GlideRecord("sys_attachment");
    getTempAttachment.addEncodedQuery("table_name=ZZ_YYsc_cart_item^sys_created_by=" + currentUser);
    getTempAttachment.orderByDesc('sys_created_on');
    getTempAttachment.query();
    if (getTempAttachment.next()) {
        var attachmentSysId = getTempAttachment.table_sys_id;
        var tradeMarket = input.tradeMarket; //inputs from client script
        var errorList = new x_938076_now_utils.MSSCustodyBulkFileUpload().bulkLevelParse(attachmentSysId, tradeMarket);
         var errorDetails = errorList.split("/");
        var errroArray = "[" + errorDetails[0] + "]";
        data.errorList = JSON.parse(errroArray); //ErrorDetails
        data.totalRecordCount = errorDetails[1]; //total error count
        data.summaryErrorRecords = errorDetails[2]; //total error count
        data.summaryValidRecords = errorDetails[3]; //total error count


        gs.info('Infy totalRecordCount ' + data.totalRecordCount);
        gs.info('Infy summaryErrorRecords ' + data.summaryErrorRecords);
        gs.info('Infy summaryValidRecords ' + data.summaryValidRecords);

    }


})();
